void formatTextSelection(const VisiblePosition& startOfSelection, const VisiblePosition& endOfSelection) {
    // Check if start is at an unsplittable element
    if (isUnsplittableElement(startOfSelection)) {
        createBlockElement(startOfSelection);
        insertPlaceholder(startOfSelection);
    }

    VisiblePosition currentPos = startOfSelection;

    // Process each paragraph in the selection
    while (currentPos != endOfSelection && !isEndOfDocument(currentPos)) {
        if (isParagraph(currentPos)) {
            formatParagraph(currentPos);

            // Check if paragraph is in a table cell
            if (isInTableCell(currentPos)) {
                applyTableCellConstraints(currentPos);
            }
        }

        // Ensure selection remains valid after each step
        if (!validateSelection(currentPos, endOfSelection)) {
            break;
        }

        movePositionToNextParagraph(currentPos);
    }

    // Final sanity check to prevent crashes from document mutations
    ensureDocumentStructureIntegrity();
}
